package org.springframework.samples.petclinic.acceptance;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.http.MediaType;
import org.springframework.security.test.context.support.WithMockUser;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultActions;
import org.springframework.transaction.annotation.Transactional;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.ObjectMapper;
import tools.jackson.databind.node.ObjectNode;

/**
 * Experimenter-owned, black-box acceptance base for PetClinic-Evolve.
 *
 * <p>Every checkpoint is a business rule on the ONE endpoint {@code POST /api/owners};
 * tests create owners and read fields back via {@code GET /api/owners/{id}}, so the
 * Spring and OfficeFloor arms are judged by identical externals.
 *
 * <p>Isolation: {@code @Transactional} rolls each test back, so count/quota rules
 * (membership number, per-day cap, per-city cap, "most common city") see only the
 * seed data plus what the test itself creates — deterministic without polluting
 * other tests. {@code @WithMockUser} authenticates as a fixed admin so the audit
 * rules can assert a known user name.
 *
 * <p>Cumulative-safety convention: {@link #ownerNode()} returns a FULLY UNIQUE
 * owner, which every rule accepts (no duplicate, no quota) at every checkpoint;
 * tests then override only the fields needed to trigger a specific rule. Reject
 * cases use data that stays rejected under all later (broader) rules.
 */
@SpringBootTest
@AutoConfigureMockMvc
@Transactional
@WithMockUser(username = "acceptance-admin", roles = {"OWNER_ADMIN", "VET_ADMIN", "ADMIN"})
public abstract class AcceptanceBase {

	private static final AtomicInteger SEQ = new AtomicInteger(0);

	@Autowired
	protected MockMvc mvc;

	@Autowired
	protected ObjectMapper om;

	protected int seq() {
		return SEQ.incrementAndGet();
	}

	// --- unique generators (avoid colliding with seed data or other tests) ---

	/** Encode n as a lowercase letter string (1->a, 26->z, 27->aa), so generated
	 *  names satisfy the base app's letters-only owner-name pattern. */
	protected String letters(int n) {
		StringBuilder sb = new StringBuilder();
		for (int x = Math.max(n, 1); x > 0; x /= 26) {
			x--;
			sb.insert(0, (char) ('a' + x % 26));
		}
		return sb.toString();
	}

	/** Unique, letters-only surname (starts with "Sur"). */
	protected String uniqueLastName() {
		return "Sur" + letters(seq());
	}

	/** Unique, letters-only given name (starts with "Fn"). Use this instead of names like
	 *  "Mem"+i: the base app enforces a letters-only owner-name pattern, so a digit in a name is
	 *  rejected with 400. Being unique it also keeps namesakeCount at 0. */
	protected String uniqueFirstName() {
		return "Fn" + letters(seq());
	}

	protected String uniqueAddress() {
		return seq() + " Test Street";
	}

	protected String uniqueCity() {
		return "Town" + seq();
	}

	/** A unique 10-digit AU mobile ('04XXXXXXXX'). Chosen so the ONE payload stays valid across the
	 *  whole telephone rule chain: 10 digits satisfies the early normalize-to-10 rule; dropping the
	 *  leading '0' yields 9 national digits, which is exactly what the later E.164 '+61' form and the
	 *  per-country length rule (+61 => 9 national digits) require. Distinct from the +1 NANP seed data. */
	protected String uniqueTelephone() {
		return String.format("04%08d", seq());
	}

	protected String uniqueEmail() {
		return "owner" + seq() + "@example.test";
	}

	protected String today() {
		return LocalDate.now().toString();
	}

	// --- payloads -----------------------------------------------------------

	/** A fully valid, fully unique owner — accepted by every rule at every checkpoint. */
	protected ObjectNode ownerNode() {
		ObjectNode o = om.createObjectNode();
		o.put("firstName", "Test");
		o.put("lastName", uniqueLastName());
		o.put("address", uniqueAddress());
		o.put("city", uniqueCity());
		o.put("telephone", uniqueTelephone());
		return o;
	}

	/** Owner payload plus a postcode. "2000" is in the NSW range and is accepted by cities with no
	 *  known region (the permissive default), so it stays valid for the random cities ownerNode() makes. */
	protected ObjectNode withPostcode(ObjectNode o) {
		o.put("postcode", "2000");
		return o;
	}

	/** Owner with a STRUCTURED address (addressLine1 / city / postcode) for the later
	 *  checkpoints that replace the flat 'address' input with structured fields. */
	protected ObjectNode structuredOwner() {
		ObjectNode o = ownerNode();
		o.remove("address");
		o.put("addressLine1", seq() + " Test Street");
		o.put("postcode", "2000");
		return o;
	}

	// --- requests -----------------------------------------------------------

	protected String json(JsonNode node) {
		try {
			return om.writeValueAsString(node);
		}
		catch (Exception e) {
			throw new RuntimeException(e);
		}
	}

	protected ResultActions createOwner(JsonNode body) throws Exception {
		return mvc.perform(post("/api/owners").contentType(MediaType.APPLICATION_JSON)
				.content(json(body)));
	}

	protected int createOwnerOk(JsonNode body) throws Exception {
		return extractId(createOwner(body).andExpect(status().is2xxSuccessful()));
	}

	/** POST with an {@code Idempotency-Key} header (for the idempotent-create rule). */
	protected ResultActions createOwnerWithKey(JsonNode body, String key) throws Exception {
		return mvc.perform(post("/api/owners").contentType(MediaType.APPLICATION_JSON)
				.header("Idempotency-Key", key).content(json(body)));
	}

	/** Create {@code n} fully-unique owners (each accepted by every rule), all in the
	 *  SAME city — used to drive the per-city capacity/warning rules. Returns nothing;
	 *  each owner differs in name/address/telephone so only the city count accumulates. */
	protected void fillCity(String city, int n) throws Exception {
		for (int i = 0; i < n; i++) {
			ObjectNode o = ownerNode();
			o.put("city", city);
			createOwnerOk(o);
		}
	}

	/** Create {@code n} fully-unique owners (each accepted by every rule), all dated
	 *  today — used to drive the per-day create-limit / bulk-signup rules. */
	protected void createMany(int n) throws Exception {
		for (int i = 0; i < n; i++) {
			createOwnerOk(ownerNode());
		}
	}

	protected ResultActions getOwner(int id) throws Exception {
		return mvc.perform(get("/api/owners/" + id));
	}

	/** Soft-delete an owner via DELETE /api/owners/{id} (asserts 2xx). The record is retained,
	 *  flagged deleted, so the create endpoint's duplicate/identity checks ignore it. */
	protected void deleteOwner(int id) throws Exception {
		mvc.perform(delete("/api/owners/" + id)).andExpect(status().is2xxSuccessful());
	}

	/** GET the owner and return its JSON body (asserts 2xx). */
	protected JsonNode fetchOwner(int id) throws Exception {
		String body = getOwner(id).andExpect(status().is2xxSuccessful())
				.andReturn().getResponse().getContentAsString();
		return om.readTree(body);
	}

	protected int extractId(ResultActions ra) throws Exception {
		String body = ra.andReturn().getResponse().getContentAsString();
		if (body != null && !body.isBlank()) {
			JsonNode n = om.readTree(body);
			if (n.hasNonNull("id")) {
				return n.get("id").asInt();
			}
		}
		String location = ra.andReturn().getResponse().getHeader("Location");
		if (location != null && location.contains("/")) {
			return Integer.parseInt(location.substring(location.lastIndexOf('/') + 1));
		}
		throw new IllegalStateException("no id in create response: " + body);
	}

	// --- pinned reference data ------------------------------------------------
	// Shared, fixed ground truth for the LOOKUP-based rules (region, postcode,
	// timezone, holidays). The rule specs enumerate these same tables, so both
	// arms implement identical mappings and a test can assert an EXACT value
	// (e.g. locality "NSW" for Sydney) instead of merely that a field exists.

	/** City -> canonical region; anything not listed derives locality "UNKNOWN". */
	protected static final Map<String, String> CITY_REGION = Map.of(
			"Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

	/** Region -> IANA timezone. */
	protected static final Map<String, String> REGION_TIMEZONE = Map.of(
			"NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");

	/** Region -> inclusive 4-digit postcode range {low, high}. */
	protected static final Map<String, int[]> REGION_POSTCODES = Map.of(
			"NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});

	/** Fixed public holidays the business-day roll skips (year of the run). */
	protected static final Set<LocalDate> HOLIDAYS = Set.of(
			LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
			LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));

	protected String region(String city) {
		return CITY_REGION.getOrDefault(city, "UNKNOWN");
	}

	protected String timezone(String city) {
		return REGION_TIMEZONE.get(region(city));
	}

	/** A postcode valid for the pinned city (low end of its region's range). */
	protected String validPostcode(String city) {
		int[] r = REGION_POSTCODES.get(region(city));
		return r == null ? null : String.valueOf(r[0]);
	}

	/** A fully-valid owner in a PINNED city with a valid postcode, so its region,
	 *  timezone and postcode-derived values are known exactly. */
	protected ObjectNode knownOwner(String city) {
		ObjectNode o = ownerNode();
		o.put("city", city);
		o.put("postcode", validPostcode(city));
		return o;
	}

	/** Roll a date forward over weekends and pinned holidays to the next business day. */
	protected LocalDate toBusinessDay(LocalDate d) {
		while (d.getDayOfWeek() == DayOfWeek.SATURDAY || d.getDayOfWeek() == DayOfWeek.SUNDAY
				|| HOLIDAYS.contains(d)) {
			d = d.plusDays(1);
		}
		return d;
	}

	// --- computed expectations ------------------------------------------------
	// Tests replicate the spec's algorithms exactly so they can assert the precise
	// derived value. The algorithms are standard (SHA-256, Luhn) and also stated in
	// the specs, so both arms produce identical outputs.

	/** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code s}. */
	protected static String sha256hex(String s) {
		try {
			byte[] digest = MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));
			StringBuilder sb = new StringBuilder(digest.length * 2);
			for (byte b : digest) {
				sb.append(String.format("%02x", b));
			}
			return sb.toString();
		}
		catch (Exception e) {
			throw new RuntimeException(e);
		}
	}

	/** First {@code n} UPPER-case hex characters of SHA-256({@code s}). */
	protected static String shaHex(String s, int n) {
		return sha256hex(s).substring(0, n).toUpperCase();
	}

	/** Luhn check digit (0-9) over the digits contained in {@code s}. */
	protected static int luhn(String s) {
		int sum = 0;
		boolean dbl = true;
		for (int i = s.length() - 1; i >= 0; i--) {
			char c = s.charAt(i);
			if (c < '0' || c > '9') {
				continue;
			}
			int d = c - '0';
			if (dbl) {
				d *= 2;
				if (d > 9) {
					d -= 9;
				}
			}
			sum += d;
			dbl = !dbl;
		}
		return (10 - (sum % 10)) % 10;
	}
}
package org.springframework.samples.petclinic.acceptance;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertTrue;
import tools.jackson.databind.JsonNode;

/** member-id: customerCode and membershipNumber are unified into 'memberId' =
 * '<REGION><FY><HASH8><CHK>'. Assert the exact, computable sub-values: the pinned region prefix and
 * the SHA-256 HASH8 over (telephone + lastName); and that the two old fields are gone. */
class AcceptanceTest extends AcceptanceBase {

	@Test
	void coreReturnsUnifiedMemberId() throws Exception {
		JsonNode r = fetchOwner(createOwnerOk(knownOwner("Sydney"))); // region NSW
		String hash8 = shaHex(r.get("telephone").asText() + r.get("lastName").asText(), 8);
		String memberId = r.get("memberId").asText();
		assertTrue(memberId.startsWith("NSW"), memberId);
		assertTrue(memberId.contains(hash8), memberId + " should contain " + hash8);
		assertTrue(!r.has("customerCode") && !r.has("membershipNumber"), "old id fields removed");
	}
}
package org.springframework.samples.petclinic.acceptance;

import java.util.List;

import org.slf4j.LoggerFactory;

import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.read.ListAppender;

/**
 * Captures events published to the dedicated {@code AUDIT} logger so audit
 * side-effects can be asserted without an implementation-specific hook.
 *
 * <pre>{@code
 * try (AuditLogCapture audit = new AuditLogCapture()) {
 *     createOwnerOk(validOwner());
 *     assertThat(audit.anyContains("...")).isTrue();
 * }
 * }</pre>
 *
 * Assumes the logging backend is Logback (the Spring Boot default). If a
 * checkpoint logs to a differently-named logger, adjust the name here.
 */
public final class AuditLogCapture implements AutoCloseable {

	private final Logger logger;

	private final ListAppender<ILoggingEvent> appender = new ListAppender<>();

	public AuditLogCapture() {
		this("AUDIT");
	}

	public AuditLogCapture(String loggerName) {
		this.logger = (Logger) LoggerFactory.getLogger(loggerName);
		this.appender.start();
		this.logger.addAppender(this.appender);
	}

	public List<String> messages() {
		return this.appender.list.stream().map(ILoggingEvent::getFormattedMessage).toList();
	}

	public boolean anyContains(String... substrings) {
		return messages().stream().anyMatch(m -> {
			for (String s : substrings) {
				if (!m.contains(s)) {
					return false;
				}
			}
			return true;
		});
	}

	/** True if some event at the given level (e.g. "WARN") contains all substrings. */
	public boolean anyAtLevel(String level, String... substrings) {
		return this.appender.list.stream()
				.filter(e -> e.getLevel().toString().equalsIgnoreCase(level))
				.map(ILoggingEvent::getFormattedMessage)
				.anyMatch(m -> {
					for (String s : substrings) {
						if (!m.contains(s)) {
							return false;
						}
					}
					return true;
				});
	}

	public int count() {
		return this.appender.list.size();
	}

	@Override
	public void close() {
		this.logger.detachAppender(this.appender);
	}
}
package org.springframework.samples.petclinic.service;

import org.junit.jupiter.api.Test;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.*;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.*;

class CustomerCodeCollisionTests {

    private final OwnerRepository ownerRepository = mock(OwnerRepository.class);

    private final ClinicServiceImpl service = new ClinicServiceImpl(mock(PetRepository.class),
        mock(VetRepository.class), ownerRepository, mock(VisitRepository.class),
        mock(SpecialtyRepository.class), mock(PetTypeRepository.class));

    private Owner newOwner() {
        Owner owner = new Owner();
        owner.setFirstName("George");
        owner.setLastName("Franklin");
        owner.setCity("Sydney");
        owner.setPostcode("2000");
        owner.setTelephone("6085551023");
        return owner;
    }

    @Test
    void keepsComputedCodeWhenUnique() {
        Owner owner = newOwner();
        service.saveOwner(owner);
        assertTrue(owner.getCustomerCode().matches("NSW-[0-9A-F]{8}"), owner.getCustomerCode());
    }

    @Test
    void appendsTwoOnFirstCollision() {
        Owner probe = newOwner();
        service.saveOwner(probe);
        String base = probe.getCustomerCode();

        when(ownerRepository.countByCustomerCode(anyString())).thenReturn(0L);
        when(ownerRepository.countByCustomerCode(base)).thenReturn(1L);
        Owner owner = newOwner();
        service.saveOwner(owner);
        assertEquals(base + "-2", owner.getCustomerCode());
    }

    @Test
    void appendsSmallestFreeSuffix() {
        Owner probe = newOwner();
        service.saveOwner(probe);
        String base = probe.getCustomerCode();

        when(ownerRepository.countByCustomerCode(anyString())).thenReturn(0L);
        when(ownerRepository.countByCustomerCode(base)).thenReturn(1L);
        when(ownerRepository.countByCustomerCode(base + "-2")).thenReturn(1L);
        when(ownerRepository.countByCustomerCode(base + "-3")).thenReturn(1L);
        Owner owner = newOwner();
        service.saveOwner(owner);
        assertEquals(base + "-4", owner.getCustomerCode());
    }
}
package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
import org.springframework.samples.petclinic.rest.validation.OwnerPostcode;
import org.springframework.samples.petclinic.rest.validation.OwnerTelephone;
import org.springframework.samples.petclinic.util.FiscalYears;

import java.time.temporal.ChronoUnit;
import java.util.Collection;
import java.util.List;
import java.util.Map;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    Map<String, String> CITY_REGIONS = Map.of(
        "Sydney", "NSW",
        "Melbourne", "VIC",
        "Brisbane", "QLD");

    Map<String, String> REGION_TIMEZONES = Map.of(
        "NSW", "Australia/Sydney",
        "VIC", "Australia/Melbourne",
        "QLD", "Australia/Brisbane");

    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials", expression = "java(toInitials(owner))")
    @Mapping(target = "selfLink", expression = "java(toSelfLink(owner))")
    @Mapping(target = "checkDigit", expression = "java(toCheckDigit(owner))")
    @Mapping(target = "membershipNumber", expression = "java(toMembershipNumber(owner))")
    @Mapping(target = "fiscalYear", expression = "java(toFiscalYear(owner))")
    @Mapping(target = "membershipPoints", expression = "java(toMembershipPoints(owner))")
    @Mapping(target = "membershipLevel", expression = "java(toMembershipLevel(owner))")
    @Mapping(target = "locality", expression = "java(toLocality(owner))")
    @Mapping(target = "contactPreference", expression = "java(toContactPreference(owner))")
    @Mapping(target = "bulkSignupWarning", expression = "java(Boolean.TRUE.equals(owner.getBulkSignupWarning()))")
    @Mapping(target = "capacityWarning", expression = "java(Boolean.TRUE.equals(owner.getCapacityWarning()))")
    @Mapping(target = "possibleDuplicate", expression = "java(owner.getPossibleDuplicateOf() != null)")
    @Mapping(target = "ageBand", expression = "java(toAgeBand(owner))")
    @Mapping(target = "telephoneDisplay", expression = "java(toTelephoneDisplay(owner))")
    @Mapping(target = "timezone", expression = "java(toTimezone(owner))")
    @Mapping(target = "salutation", expression = "java(toSalutation(owner))")
    @Mapping(target = "ownerSegment", expression = "java(toOwnerSegment(owner))")
    @Mapping(target = "sharesHousehold", ignore = true)
    OwnerDto toOwnerDto(Owner owner);

    /**
     * '&lt;title&gt; &lt;lastName&gt;', or just the last name when the owner has no title.
     */
    default String toSalutation(Owner owner) {
        return owner.getTitle() == null ? owner.getLastName() : owner.getTitle() + " " + owner.getLastName();
    }

    /**
     * The stored E.164 telephone formatted for humans, e.g. '+61 412 345 678'.
     */
    default String toTelephoneDisplay(Owner owner) {
        return OwnerTelephone.format(owner.getTelephone());
    }

    /**
     * The owner's age in completed years on the registration date: 'MINOR' under 18, 'ADULT' 18-64,
     * 'SENIOR' 65 or over. Absent when the owner has no birth date or registration date.
     */
    default String toAgeBand(Owner owner) {
        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
            return null;
        }
        long age = ChronoUnit.YEARS.between(owner.getBirthDate(), owner.getRegistrationDate());
        if (age < 18) {
            return "MINOR";
        }
        return age < 65 ? "ADULT" : "SENIOR";
    }

    /**
     * The REGION part of the owner's customer code ('&lt;REGION&gt;-&lt;HASH8&gt;', optionally followed by a
     * '-&lt;n&gt;' de-duplication suffix); for owners without a
     * customer code, the region derived by {@link OwnerPostcode#regionOf(String, String)}.
     */
    default String toLocality(Owner owner) {
        String code = owner.getCustomerCode();
        int dash = code == null ? -1 : code.indexOf('-');
        if (dash > 0) {
            return code.substring(0, dash);
        }
        return OwnerPostcode.regionOf(owner.getPostcode(), owner.getCity());
    }

    /**
     * The IANA timezone of the owner's {@link #toLocality(Owner) locality} from {@link #REGION_TIMEZONES};
     * absent for any other locality.
     */
    default String toTimezone(Owner owner) {
        return REGION_TIMEZONES.get(toLocality(owner));
    }

    /** The lowest {@link #toMembershipLevel(Owner) membership level} of the 'PREMIUM' segment tier. */
    int PREMIUM_MEMBERSHIP_LEVEL = 3;

    /**
     * '&lt;TIER&gt;_&lt;AREA&gt;': TIER is 'PREMIUM' when the {@link #toMembershipLevel(Owner) membership level}
     * is at least {@link #PREMIUM_MEMBERSHIP_LEVEL}, otherwise 'STANDARD'; AREA is 'METRO' when the
     * {@link #toLocality(Owner) locality} is a known region of {@link #CITY_REGIONS}, otherwise 'REGIONAL'.
     */
    default String toOwnerSegment(Owner owner) {
        String tier = toMembershipLevel(owner) >= PREMIUM_MEMBERSHIP_LEVEL ? "PREMIUM" : "STANDARD";
        String area = CITY_REGIONS.containsValue(toLocality(owner)) ? "METRO" : "REGIONAL";
        return tier + "_" + area;
    }

    /**
     * 'EMAIL' when the owner has an email address, otherwise 'PHONE'.
     */
    default String toContactPreference(Owner owner) {
        return owner.getEmail() != null && !owner.getEmail().isBlank() ? "EMAIL" : "PHONE";
    }

    /** Membership points for an owner with an email address. */
    int EMAIL_MEMBERSHIP_POINTS = 2;

    /** Membership points for an owner without namesakes. */
    int NO_NAMESAKE_MEMBERSHIP_POINTS = 1;

    /** Membership points for a household of at least {@link #HOUSEHOLD_MEMBERSHIP_SIZE} members. */
    int HOUSEHOLD_MEMBERSHIP_POINTS = 2;

    /** The household size earning {@link #HOUSEHOLD_MEMBERSHIP_POINTS}. */
    int HOUSEHOLD_MEMBERSHIP_SIZE = 3;

    /** Membership points for a tenure of at least {@link #TENURE_MEMBERSHIP_FISCAL_YEARS} elapsed fiscal years. */
    int TENURE_MEMBERSHIP_POINTS = 3;

    /** {@link #TENURE_MEMBERSHIP_POINTS} requires a tenure of at least this many elapsed fiscal years. */
    int TENURE_MEMBERSHIP_FISCAL_YEARS = 1;

    /** The highest membership level. */
    int MAX_MEMBERSHIP_LEVEL = 4;

    /**
     * The membership points of a newly created owner. A new owner has zero tenure, so this never
     * includes {@link #TENURE_MEMBERSHIP_POINTS}.
     */
    default Integer toMembershipPoints(Owner owner) {
        return membershipPoints(owner, 0);
    }

    /**
     * The membership level of a newly created owner, derived from {@link #toMembershipPoints(Owner)}
     * and capped at the owner's membership level cap, when it has one.
     */
    default Integer toMembershipLevel(Owner owner) {
        int level = membershipLevel(toMembershipPoints(owner));
        return owner.getMembershipLevelCap() == null ? level : Math.min(level, owner.getMembershipLevelCap());
    }

    /**
     * Starts at 0, adds {@link #EMAIL_MEMBERSHIP_POINTS} when an email is present,
     * {@link #NO_NAMESAKE_MEMBERSHIP_POINTS} when the owner has no namesakes,
     * {@link #HOUSEHOLD_MEMBERSHIP_POINTS} for a household of {@link #HOUSEHOLD_MEMBERSHIP_SIZE} or more
     * members and {@link #TENURE_MEMBERSHIP_POINTS} for a tenure of at least
     * {@link #TENURE_MEMBERSHIP_FISCAL_YEARS} elapsed fiscal years (see {@link FiscalYears#between}).
     */
    default int membershipPoints(Owner owner, long tenureFiscalYears) {
        int points = 0;
        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
            points += EMAIL_MEMBERSHIP_POINTS;
        }
        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
            points += NO_NAMESAKE_MEMBERSHIP_POINTS;
        }
        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= HOUSEHOLD_MEMBERSHIP_SIZE) {
            points += HOUSEHOLD_MEMBERSHIP_POINTS;
        }
        if (tenureFiscalYears >= TENURE_MEMBERSHIP_FISCAL_YEARS) {
            points += TENURE_MEMBERSHIP_POINTS;
        }
        return points;
    }

    /**
     * Maps membership points to a level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and
     * {@link #MAX_MEMBERSHIP_LEVEL} for 6 or more.
     */
    default int membershipLevel(int points) {
        return Math.min(points / 2 + 1, MAX_MEMBERSHIP_LEVEL);
    }

    /**
     * 'FY&lt;YY&gt;' for the fiscal year (starting 1 July) containing the business-day adjusted
     * registration date; absent when the owner has no registration date.
     */
    default String toFiscalYear(Owner owner) {
        return FiscalYears.label(owner.getRegistrationDate());
    }

    /**
     * Builds the membership number '&lt;customerCode&gt;-M&lt;YY&gt;', where YY is the last two digits of
     * the fiscal year containing the registration date.
     */
    default String toMembershipNumber(Owner owner) {
        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
            return null;
        }
        return String.format("%s-M%02d", owner.getCustomerCode(),
            FiscalYears.twoDigit(owner.getRegistrationDate()));
    }

    /**
     * The Luhn check digit over the digits of the customer code, ignoring non-digit characters.
     */
    default Integer toCheckDigit(Owner owner) {
        String code = owner.getCustomerCode();
        if (code == null) {
            return null;
        }
        int sum = 0;
        boolean doubled = true;
        for (int i = code.length() - 1; i >= 0; i--) {
            char c = code.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int digit = c - '0';
            if (doubled) {
                digit *= 2;
                if (digit > 9) {
                    digit -= 9;
                }
            }
            sum += digit;
            doubled = !doubled;
        }
        return (10 - sum % 10) % 10;
    }

    /**
     * The relative URI of the owner resource, '/api/owners/&lt;id&gt;'; absent for an unsaved owner.
     */
    default String toSelfLink(Owner owner) {
        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
    }

    default String toInitials(Owner owner) {
        return initial(owner.getFirstName()) + initial(owner.getLastName());
    }

    private static String initial(String name) {
        return name == null || name.isEmpty() ? "" : Character.toUpperCase(name.charAt(0)) + ".";
    }

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    @Mapping(target = "customerCode", ignore = true)
    @Mapping(target = "householdId", ignore = true)
    @Mapping(target = "namesakeCount", ignore = true)
    @Mapping(target = "householdSize", ignore = true)
    @Mapping(target = "membershipLevelCap", ignore = true)
    @Mapping(target = "bulkSignupWarning", ignore = true)
    @Mapping(target = "capacityWarning", ignore = true)
    @Mapping(target = "possibleDuplicateOf", ignore = true)
    @Mapping(target = "deleted", ignore = true)
    @Mapping(target = "idempotencyKey", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

